class Solution {
public:
    long long minDamage(int power, vector<int>& damage, vector<int>& health) {
        int n = damage.size();
        vector<long long> t(n);
        for (int i = 0; i < n; ++i) t[i] = (health[i] + power - 1) / power;
        vector<int> idx(n); iota(idx.begin(), idx.end(), 0);
        sort(idx.begin(), idx.end(), [&](int a, int b){
            return damage[a] * t[b] > damage[b] * t[a];
        });
        long long rem = accumulate(damage.begin(), damage.end(), 0LL), ans = 0;
        for (int i : idx) { ans += rem * t[i]; rem -= damage[i]; }
        return ans;
    }
};

