class Solution {
    public long minDamage(int power, int[] damage, int[] health) {
        int n = damage.length;
        long[] t = new long[n];
        for (int i = 0; i < n; ++i) t[i] = (health[i] + power - 1) / power;
        Integer[] idx = new Integer[n];
        for (int i = 0; i < n; ++i) idx[i] = i;
        java.util.Arrays.sort(idx, (a, b) ->
            Long.compare((long)damage[b] * t[a], (long)damage[a] * t[b]));
        long rem = 0, ans = 0;
        for (int d : damage) rem += d;
        for (int i : idx) { ans += rem * t[i]; rem -= damage[i]; }
        return ans;
    }
}

