var minDamage = function(power, damage, health) {
    const n = damage.length;
    const t = health.map(h => Math.ceil(h / power));
    const idx = [...Array(n).keys()];
    idx.sort((a, b) => damage[b] * t[a] - damage[a] * t[b]);
    let rem = damage.reduce((x, y) => x + y, 0), ans = 0;
    for (const i of idx) { ans += rem * t[i]; rem -= damage[i]; }
    return ans;
};
